import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.cyF4XceO.js";const h=JSON.parse('{"title":"Project and Form lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"spec/project-lifecycle.md","filePath":"spec/project-lifecycle.md"}'),r={name:"spec/project-lifecycle.md"};function n(c,e,s,l,d,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="project-and-form-lifecycle" tabindex="-1">Project and Form lifecycle <a class="header-anchor" href="#project-and-form-lifecycle" aria-label="Permalink to &quot;Project and Form lifecycle&quot;">​</a></h1><p>Takoform is an <strong>Experimental specification and tooling project</strong> for portable desired-state contracts between infrastructure-as-code clients and resource hosts. It is not currently an industry standard, a certification authority, a universal cloud API, or a promise that an existing Resource can move between backends without migration.</p><p>This document is the authority for current project positioning, Form maturity, and the evidence required to change maturity. Exact version compatibility is defined in <a href="./versioning.html"><code>versioning.md</code></a>; package and implementation conformance are defined in <a href="./conformance.html"><code>conformance.md</code></a>.</p><p>Machine authority is scoped by identity family. The retained central epochs and their proposals are recorded in <a href="../forms/lifecycle.json"><code>../forms/lifecycle.json</code></a>. Its repository-local authoring schema is <a href="../forms/lifecycle.schema.json"><code>../forms/lifecycle.schema.json</code></a>, and <code>standard-form-conformance verify</code> is the fail-closed semantic validator. The JSON Schema documents shape; the validator additionally verifies referenced files, exact package bytes, transition order, owner continuity, independent maintainers, and the pinned Legacy inventory. The authoring schema has no public <code>$id</code> and is not a published Form contract. Current family maturity and exact identity are recorded in the generated family candidate set; for the Beta Edge family that is <a href="../forms/candidates/edge/v1beta1/candidate-set.json"><code>../forms/candidates/edge/v1beta1/candidate-set.json</code></a>. The provider compatibility copy is independently locked in <a href="../release/provider-form-identities.json"><code>../release/provider-form-identities.json</code></a>.</p><h2 id="independent-facts" tabindex="-1">Independent facts <a class="header-anchor" href="#independent-facts" aria-label="Permalink to &quot;Independent facts&quot;">​</a></h2><p>The following facts MUST remain independent:</p><table tabindex="0"><thead><tr><th>Fact</th><th>Authority</th><th>Meaning</th></tr></thead><tbody><tr><td>Form maturity</td><td>Takoform lifecycle record</td><td>Confidence in one portable contract</td></tr><tr><td>Package publication</td><td>Takoform publisher evidence</td><td>Exact bytes can be retrieved and authenticated</td></tr><tr><td>Provider compatibility</td><td>Provider release and compatibility data</td><td>A provider can represent an exact FormRef and preserve its own state contract</td></tr><tr><td>Host Support</td><td>Named host evidence</td><td>One host implements the lifecycle for one exact FormRef</td></tr><tr><td>Form Activation</td><td>Host/operator policy</td><td>A supported FormRef is usable in a particular scope</td></tr><tr><td>Service Offering</td><td>Commercial platform</td><td>Capacity, price, availability, and support for an exact supported FormRef</td></tr></tbody></table><p>No package, provider release, generated catalog entry, host report, activation, or Service Offering MAY by itself promote Form maturity. A host implementation MUST NOT describe its support decision as Takoform approval or certification.</p><p>The Beta Host API and provider v2.1 path follow the scoped release policy in <a href="./publication-freeze.html"><code>publication-freeze.md</code></a>. Open independent-host, third-party-ecosystem, and Cloud-GA evidence remains required for later Stable/GA claims and Form Package/public-service publication, but does not block a stable provider release that embeds the exact Beta identities.</p><h2 id="form-families" tabindex="-1">Form Families <a class="header-anchor" href="#form-families" aria-label="Permalink to &quot;Form Families&quot;">​</a></h2><p>Forms are grouped into named Form Families with namespaced API groups (<a href="./form-families.html"><code>form-families.md</code></a>, <a href="./decisions/0009-form-families-and-namespaced-api-versions.html">decision 0009</a>). A family is a catalog and namespace fact only; its API channel does not confer Form maturity. Each member still has an explicit maturity classification. The current <code>edge.forms.takoform.com/v1beta1</code> candidate set contains exactly 15 <code>0.1.0</code> Forms and classifies all of them Experimental. Its unpublished <code>packages.forms.takoform.com/v1alpha4</code> artifacts are a separate publication fact. Adding a Form to a family, or publishing one family member, promotes nothing else. The retained <code>forms.takoform.com/v1alpha2</code> candidates are superseded provider-v2 preview source (<a href="./decisions/0035-beta-contracts-ship-in-stable-provider-v2-1.html">decision 0035</a>); they are not a published current Form line and are not the basis for new specification work.</p><h2 id="form-lifecycle" tabindex="-1">Form lifecycle <a class="header-anchor" href="#form-lifecycle" aria-label="Permalink to &quot;Form lifecycle&quot;">​</a></h2><h3 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h3><p>A Form Proposal is mutable, unversioned design material. It has no public FormRef, package release, compatibility promise, or maturity claim. A Proposal MAY change incompatibly or be removed without deprecation.</p><p>A Proposal MUST name:</p><ul><li>the real workload and consumer that need it;</li><li>the maintainer responsible for its portable semantics;</li><li>at least one intended host implementation;</li><li>the desired-state boundary and the decisions left to the host;</li><li>lifecycle risks, including replacement, data loss, delete, import, and drift;</li><li>the credential, network, artifact, and secret boundary;</li><li>relevant prior art and the concrete reason an existing abstraction is not sufficient.</li></ul><p>A Proposal MUST also classify every desired field using the portable boundary in <a href="./portability-boundary.html"><code>portability-boundary.md</code></a>. A first host or commercial offering is workload evidence, not permission to copy its product model into a Form.</p><p>The prior-art review MUST include OCCI, CIMI, TOSCA where applicable, Kubernetes/Crossplane APIs, and established Terraform/OpenTofu provider APIs for the represented capability. The review is a design obligation, not a claim of compliance.</p><p>Every Proposal registry entry records all five prior-art families explicitly and marks each <code>applicable</code> or <code>not-applicable</code> with a finding. A Proposal entry cannot contain a FormRef, package digest, version, maturity state, or release identity: strict decoding rejects those fields. Its ID is only an internal link from later lifecycle evidence and is not a public compatibility identity.</p><p>Creating or revising a Proposal does not require release authority. Publication does.</p><p>The authoring workspace and copyable review outline are <a href="./../proposals/"><code>../proposals/</code></a>. A Proposal exists in current authority only when its document and matching registry entry are both present. The semantic validator compiles the repository-local authoring schema on every verification; an uncompiled or drifting schema is a failing gate, not advisory documentation.</p><h3 id="experimental" tabindex="-1">Experimental <a class="header-anchor" href="#experimental" aria-label="Permalink to &quot;Experimental&quot;">​</a></h3><p>An Experimental Form is a reproducible public contract on a <code>0.x</code> version line. Its released bytes are immutable, but its semantics may still change under the <code>0.x</code> policy in <a href="./versioning.html"><code>versioning.md</code></a>.</p><p>A Proposal MAY become Experimental only when all of the following are present:</p><ul><li>one exact canonical Form Definition and FormRef;</li><li>positive and negative fixtures covering the portable semantics;</li><li>a host implementation that exercises create/read/update/delete and the applicable observe, refresh, import, replacement, and recovery paths;</li><li>known limitations and unresolved portability questions;</li><li>compatibility classification and a migration or rollback note;</li><li>security-boundary review;</li><li>generated reference and narrative documentation that agree;</li><li>immutable FormRef and canonical Definition identity;</li><li>package provenance, signature, and public readback plan before package publication.</li></ul><p>Passing these checks prepares a publication. It does not authorize one.</p><p>An immutable Definition contains no maturity field. The scoped lifecycle or family record is the authority for Experimental, Stable, and later Legacy transitions, so a maturity change never requires rewriting or duplicating a fact inside Definition or package bytes. A provider-first release may lock an Experimental FormRef and Definition/package digest before the package artifact is published; that lock is still immutable and package publication remains a separate operation.</p><h3 id="stable" tabindex="-1">Stable <a class="header-anchor" href="#stable" aria-label="Permalink to &quot;Stable&quot;">​</a></h3><p>A Stable Form is an evidence-earned portable contract. Stable is not a central approval applied to a preferred subset.</p><p>An Experimental Form MUST NOT become Stable until:</p><ul><li>at least two independently maintained host implementations exercise the same exact semantics, or equivalent evidence demonstrates that the contract is implementable without relying on one host&#39;s private model;</li><li>real consumers have operated the Form across a documented compatibility window;</li><li>immutable fields, replacement, import, drift, delete, and recovery behavior agree across implementations;</li><li>interoperability has been exercised using packages published by a party other than at least one consuming host;</li><li>migration from the latest Experimental line is documented and tested;</li><li>deprecation and security-revocation procedures have been exercised on a real release line;</li><li>known limitations do not contradict the claimed portable semantics.</li></ul><p>Stable commits Takoform to the stable SemVer rules in <a href="./versioning.html"><code>versioning.md</code></a>. It does not guarantee that every host supports the Form or that a commercial platform offers it.</p><p>Takosumi GA is a qualification checkpoint, not an automatic transition. At that checkpoint only contracts with the required evidence above may mint a Stable <code>1.0.0</code> identity; all others remain Experimental/Beta without being renamed or overwritten.</p><p>The machine record requires the exact transition history <code>proposal → experimental → stable</code>, two distinct host subjects with two independently named maintainers, real-consumer evidence, lifecycle agreement, interoperability, independent publication, migration, deprecation-exercise, and security-revocation-exercise files. A direct Proposal-to-Stable record is invalid even if other evidence is present.</p><h3 id="legacy" tabindex="-1">Legacy <a class="header-anchor" href="#legacy" aria-label="Permalink to &quot;Legacy&quot;">​</a></h3><p>A Legacy Form is an immutable published identity retained for compatibility, recovery, and explicit migration but no longer used as the basis for new specification work. Legacy status MUST identify the reason, exact affected FormRefs, successor or alternative when one exists, new-create policy, and the retained read/observe/delete/recovery behavior.</p><p>Moving a Form to Legacy MUST NOT delete or overwrite its definition, package, tag, signature, revocation evidence, or migration material.</p><h2 id="existing-public-line" tabindex="-1">Existing public line <a class="header-anchor" href="#existing-public-line" aria-label="Permalink to &quot;Existing public line&quot;">​</a></h2><p>The public line created before decision <a href="./decisions/0004-takoform-is-an-experimental-specification.html"><code>0004</code></a> is a retained <strong>Legacy line</strong>. Its exact artifacts and historical <code>standard</code> and <code>portable-standard</code> fields remain verifiable facts about those documents, but they are not current maturity states and do not define an approved subset.</p><p>In particular:</p><ul><li>the generated 34-Form <code>standard</code> catalog is not evidence that 34 Forms have satisfied the Stable criteria above;</li><li>the retained ten-Form <code>portable-standard</code> admission closure is historical signed lifecycle evidence for exact identities, not a normative ranking;</li><li>a Takosumi or Takosumi Cloud implementation count is Host Support or Service Offering data, not Form maturity;</li><li>existing Resources keep their exact pins and MUST retain safe observation, deletion, recovery, and explicit migration paths.</li></ul><p>New lifecycle data MUST NOT rewrite the immutable legacy Form Definitions merely to replace their historical status field. Reader-facing tools MUST project the current Legacy classification alongside the original document truth.</p><p>The top-level <code>legacy</code> object pins that pre-reset line by a canonical digest of every exact public release identity. <code>currentForms</code> is scoped to the retained central post-reset epoch; current namespaced families use their own generated candidate-set maturity record. This separation prevents the old generated catalog or admission subset from being silently reinterpreted as new maturity evidence.</p><h2 id="change-authority" tabindex="-1">Change authority <a class="header-anchor" href="#change-authority" aria-label="Permalink to &quot;Change authority&quot;">​</a></h2><p>Every public Form change MUST update, in the same reviewed change set:</p><ul><li>canonical definition and fixtures;</li><li>compatibility classification and migration effect;</li><li>lifecycle and security risks;</li><li>generated reference documentation;</li><li>the applicable scoped maturity record;</li><li>provider compatibility only when provider behavior changes;</li><li>Host Support only when the named host&#39;s evidence changes.</li></ul><p>Machine checks MUST fail closed on an unknown lifecycle state, a missing owner, a changed published byte, a maturity claim inferred from provider/host/Cloud data, or a direct Proposal-to-Stable transition.</p><h2 id="deprecation-and-security-revocation" tabindex="-1">Deprecation and security revocation <a class="header-anchor" href="#deprecation-and-security-revocation" aria-label="Permalink to &quot;Deprecation and security revocation&quot;">​</a></h2><p>Deprecation is a consumer migration contract. It identifies the reason, successor, timing for rejecting new create/apply, retained lifecycle behavior, and migration instructions.</p><p>Security revocation is separate and append-only as defined by <a href="./trust/"><code>trust/</code></a>. It may block new creation, update, or activation while the referenced bytes remain available for observation, deletion, recovery, or an explicit operator evacuation path.</p>',50)])])}const f=a(r,[["render",n]]);export{h as __pageData,f as default};
